/**
 * Domain types. They come from the OpenAPI document (`schema.d.ts` is generated by `npm run api:types`),
 * so a change in the backend contract shows up here as a compile error instead of a runtime surprise.
 */
import type { components } from './schema';

type S = components['schemas'];

export type Lang = S['Lang'];
export type PageMeta = S['PageMeta'];
export type Image = S['Image'];
export type PostCard = S['PostCard'];
export type SpotlightPost = S['SpotlightPost'];
export type PostDetail = S['PostDetail'];
export type PhotoCard = S['PhotoCard'];
export type PhotoCardDetail = S['PhotoCardDetail'];
export type Video = S['Video'];
export type VideoDetail = S['VideoDetail'];
export type Category = S['Category'];
export type TagWithCount = S['TagWithCount'];
export type Comment = S['Comment'];
export type HomePayload = S['HomePayload'];
export type NamedRef = S['NamedRef'];
export type Ad = S['Ad'];
export type AdPlacement = S['AdPlacement'];

export type ReaderSession = NonNullable<S['ReaderSession']['data']>;
export type Reader = ReaderSession['reader'];

export interface Envelope<T, M = undefined> {
  data: T;
  meta?: M;
}
export type Paged<T> = { data: T[]; meta: PageMeta };
